class ResourceOwner {
    int* ptr;
    size_t size;
public:
    // Ctor/Dtor assumed

    // 1. Move Constructor: Takes rvalue reference (&&)
    ResourceOwner(ResourceOwner&& other) noexcept
        : ptr(other.ptr), size(other.size) // Steal resource
    {
        other.ptr = nullptr; // Nullify source
        other.size = 0;
    }

    // 2. Move Assignment Operator
    ResourceOwner& operator=(ResourceOwner&& other) noexcept {
        if (this != &other) {
            delete[] ptr;         // Release current resource

            ptr = other.ptr;      // Steal
            size = other.size;

            other.ptr = nullptr;  // Nullify source
            other.size = 0;
        }
        return *this;
    }
};
